class AddressPipeline(BaseEstimator, TransformerMixin):
    """Parser-centric pipeline with single-item execution and lazy chunked streaming."""

    def __init__(
        self,
        parser: HierarchicalAddressParser | None = None,
        *,
        auto_correct: bool = True,
    ) -> None:
        self.parser = parser
        self.auto_correct = auto_correct
        self._default_parser: HierarchicalAddressParser | None = None

    @property
    def active_parser(self) -> HierarchicalAddressParser:
        """Lazily initialize or return default underlying parser."""
        if self.parser is not None:
            return self.parser
        if self._default_parser is None:
            self._default_parser = HierarchicalAddressParser()
        return self._default_parser

    def __call__(
        self,
        address: str,
        *,
        auto_correct: bool | None = None,
        **kwargs: Any,
    ) -> ParsedAddress:
        """Execute the pipeline on a single address string."""
        parser_formatter = kwargs.pop("formatter", None)
        extract_contact = kwargs.pop("extract_contact", True)
        use_auto = self.auto_correct if auto_correct is None else auto_correct
        return self.active_parser.parse(
            address,
            auto_correct=use_auto,
            formatter=parser_formatter,
            extract_contact=extract_contact,
        )

    def parse(
        self,
        address: str,
        *,
        auto_correct: bool | None = None,
        **kwargs: Any,
    ) -> ParsedAddress:
        """Alias for __call__."""
        return self(address, auto_correct=auto_correct, **kwargs)

    def pipe(
        self,
        stream: Iterable[str],
        *,
        batch_size: int = 512,
        auto_correct: bool | None = None,
        **kwargs: Any,
    ) -> Iterator[ParsedAddress]:
        """Lazy streaming generator for high-throughput address processing."""
        parser_formatter = kwargs.pop("formatter", None)
        kwargs.pop("extract_contact", None)
        use_auto = self.auto_correct if auto_correct is None else auto_correct
        parser = self.active_parser
        for chunk in chunk_iterable(stream, batch_size):
            batch_res = parser.parse_batch(
                chunk,
                auto_correct=use_auto,
                formatter=parser_formatter,
            )
            yield from batch_res.results

    def __sklearn_clone__(self) -> AddressPipeline:
        """Clone pipeline while preserving defensive copies in ``__init__``."""
        try:
            from sklearn.base import clone as sk_clone  # pyright: ignore[reportMissingTypeStubs]
        except ImportError:
            from .adapters.sklearn import BaseEstimator

            return BaseEstimator.__sklearn_clone__(self)  # type: ignore[attr-defined]

        cloned_parser = sk_clone(self.parser) if self.parser is not None else None
        return self.__class__(
            parser=cloned_parser,  # pyright: ignore[reportArgumentType]
            auto_correct=self.auto_correct,
        )

    def get_params(self, deep: bool = True) -> dict[str, Any]:
        params: dict[str, Any] = {
            "parser": self.parser,
            "auto_correct": self.auto_correct,
        }
        if deep and self.parser is not None and not isinstance(self.parser, type):
            getter = getattr(self.parser, "get_params", None)
            if callable(getter):
